"use client"

import React, { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { Skeleton } from "@/components/ui/skeleton"
import { useCreateChat } from "@/hooks/api/chats"
import { useStreamingChats } from "@/features/chat/PendingChatContext"
import logger from "@/lib/logger"

function ChatLoading() {
  return (
    <div className="mx-auto w-full max-w-3xl h-full flex flex-col p-6 gap-4">
      <div className="flex-1 overflow-y-auto">
        <div className="flex flex-col gap-4">
          <Skeleton className="w-48 h-12 rounded-lg self-end" />
          <Skeleton className="w-64 h-16 rounded-lg self-end" />
        </div>
      </div>
      <div>
        <Skeleton className="w-full h-10" />
      </div>
    </div>
  )
}

export default function NewChatPage() {
  const router = useRouter()
  const createChatMutation = useCreateChat()
  const { setStreamingStatus } = useStreamingChats()
  const [isCreating, setIsCreating] = useState(false)

  useEffect(() => {
    const handleNewChatCreation = async () => {
      // Check if we have pending new chat data
      const pendingMessage = sessionStorage.getItem('pending-new-chat-message')
      const pendingCourse = sessionStorage.getItem('pending-new-chat-course')
      const tempChatId = sessionStorage.getItem('pending-new-chat-temp-id')

      if (pendingMessage && pendingCourse && tempChatId && !isCreating) {
        setIsCreating(true)
        
        try {
          const course = JSON.parse(pendingCourse)
          logger.info('Creating real chat from /chat page')
          
          // Create real chat with just the user message
          const createRequest = {
            initialMessages: [
              { role: 'user', content: pendingMessage }
            ]
          }
          
          const newChat = await createChatMutation.mutateAsync(createRequest)
          logger.info('Created real chat:', { chatId: newChat.id, title: newChat.title })
          
          // Transfer streaming status from temp to real chat
          setStreamingStatus(tempChatId, 'Creating chat...', false) // Remove temp
          setStreamingStatus(newChat.id, newChat.title, true) // Add real with streaming
          
          // Store initial message for the streaming logic
          sessionStorage.setItem(`initial-message-${newChat.id}`, pendingMessage)
          
          // Clean up pending data
          sessionStorage.removeItem('pending-new-chat-message')
          sessionStorage.removeItem('pending-new-chat-course')
          sessionStorage.removeItem('pending-new-chat-temp-id')
          
          // Navigate to the real chat
          logger.info('Redirecting to real chat:', { chatId: newChat.id })
          router.replace(`/chat/${newChat.id}`)
          
        } catch (error) {
          console.error('Failed to create chat:', error)
          // Clean up temp streaming status on error
          if (tempChatId) {
            setStreamingStatus(tempChatId, 'Creating chat...', false)
          }
          // Navigate back to dashboard on error
          router.replace('/')
        }
      } else if (!pendingMessage) {
        // No pending chat creation, redirect to dashboard
        router.replace('/')
      }
    }

    handleNewChatCreation()
  }, [router, createChatMutation, setStreamingStatus, isCreating])

  return <ChatLoading />
}